		// ── Still Alive, Release 5-2: tile fire ───────────────────────────────
	/**
	 * Damage to anything standing in a burning tile. 1.
	 *
	 * Deliberately half of the C#'s `BASE_ISONFIRE_FIRE_DAMAGE` (2): standing in
	 * fire is worse than being on fire, and the C#'s comment says why -- flame
	 * weapons deal their own impact damage and the per-turn figure must not
	 * double-count it.
	 */
	private static readonly BASE_TILE_FIRE_DAMAGE = 1;

	/** C# `FIRE_FUEL_PER_WOOD_PLANK` -- `RogueGame.cs:393`, Release 7-6. */
	private static readonly FIRE_FUEL_PER_WOOD_PLANK = 90;
	/**
	 * Percent chance per adjacent flammable tile that a fire spreads.
	 *
	 * The C#'s own note: "even tiny increases make fire spread significantly". It
	 * went 6 -> 5 for that reason. At 5%, with eight neighbours and no memory of
	 * what has already burnt, a fire eats a carpeted room in a few turns -- which
	 * is the point, and the reason `isScorched` exists.
	 */
	private static readonly TILE_FIRE_SPREAD_CHANCE = 5;
	/** Rain accelerates a fire's death; clear weather is the slow case. */
	/** C# `:378`, Release 5-7. Per-turn damage to an actor that is *on fire*. */
	private static readonly BASE_ISONFIRE_FIRE_DAMAGE = 2;
	/**
	 * C# `:380`, Release 6-6. Standing in a burning tile gives the actor a small
	 * chance of *becoming* fire, which is a different and much longer-lived state
	 * than the tile fire it came from. This is `Feature.TileFires`'s last arm.
	 */
	private static readonly CATCH_ONFIRE_FROM_TILE_CHANCE = 25;
	/**
	 * C# `:385`, Release 7-6. Stop-drop-and-roll on Wait. 50% -- and unlike the
	 * weather extinguishments this one applies to *everyone*, undeads included, since
	 * it is a deliberate action rather than a change in the environment.
	 */
	private static readonly ON_WAIT_EXTINGUISH_FIRE_CHANCE = 50;
	private static readonly CLEAR_WEATHER_FIRE_EXTINGUISH_CHANCE = 33;
	private static readonly LIGHT_RAIN_FIRE_EXTINGUISH_CHANCE = 70;
	private static readonly HEAVY_RAIN_FIRE_EXTINGUISH_CHANCE = 80;

// ── Method stubs (filled in by later slices) ─────────────────────────

	// C# AddMessage — RogueGame.cs:833
	AddMessage(msg: Message): void {
		// ignore empty messages
		if (msg.text.length === 0) return;

		// Clear if too much messages.
		if (this.m_MessageManager.count >= MAX_MESSAGES)
			this.m_MessageManager.clear();

		// Format message: <turn> <Text>
		msg.text = `${this.m_Session.worldTime.turnCounter} ${this.Capitalize(msg.text)}`;

		// Add.
		this.m_MessageManager.add(msg);
	}

	// C# AddMessageIfAudibleForPlayer — RogueGame.cs:853
	AddMessageIfAudibleForPlayer(location: Location, msg: Message): void {
		if (msg == null) throw new TypeError("msg");

		// 1. Audible to player?
		if (this.m_Player != null) {
			// if sleeping can't hear.
			if (this.m_Player.isSleeping) return;

			// can't hear if not same map.
			if (location.map !== this.m_Player.location.map) return;

			// can hear if close enough.
			if (
				this.m_Rules.stdDistance(
					this.m_Player.location.position,
					location.position,
				) <= this.m_Player.audioRange
			) {
				// hear.
				msg.color = this.PLAYER_AUDIO_COLOR;
				this.AddMessage(msg);

				// if waiting, interupt.
				if (this.m_IsPlayerLongWait) this.m_IsPlayerLongWaitForcedStop = true;

				// redraw.
				this.RedrawPlayScreen();
			}
		}
	}

	// C# MakePlayerCentricMessage — RogueGame.cs:892
	MakePlayerCentricMessage(eventText: string, position: Point): Message {
		const playerPos = this.m_Player.location.position;
		const vDir = new Point(position.x - playerPos.x, position.y - playerPos.y);
		const text =
			`${eventText} ${Math.floor(this.m_Rules.stdDistanceOf(vDir))} tiles to the ` +
			`${Direction.approximateFromVector(vDir.x, vDir.y)}.`;
		return new Message(text, this.m_Session.worldTime.turnCounter);
	}

	// C# MakeErrorMessage — RogueGame.cs:899
	MakeErrorMessage(text: string): Message {
		return new Message(text, this.m_Session.worldTime.turnCounter, Color.Red);
	}

	// C# MakeYesNoMessage — RogueGame.cs:904
	MakeYesNoMessage(question: string): Message {
		return new Message(
			`${question}? Y to confirm, N to cancel`,
			this.m_Session.worldTime.turnCounter,
			Color.Yellow,
		);
	}

	// C# ActorVisibleIdentity — RogueGame.cs:914
	ActorVisibleIdentity(actor: Actor): string {
		return this.IsVisibleToPlayer(actor) ? actor.theName : "someone";
	}

	// C# ObjectVisibleIdentity — RogueGame.cs:924
	ObjectVisibleIdentity(mapObj: MapObject): string {
		return this.IsVisibleToPlayer(mapObj) ? mapObj.theName : "something";
	}

	// C# MakeMessage — RogueGame.cs:929 (+7 overloads)
	MakeMessage(actor: Actor, doWhat: string): Message;
	MakeMessage(actor: Actor, doWhat: string, color: Color): Message;
	MakeMessage(
		actor: Actor,
		doWhat: string,
		target: Actor,
		phraseEnd?: string,
	): Message;
	MakeMessage(
		actor: Actor,
		doWhat: string,
		target: MapObject,
		phraseEnd?: string,
	): Message;
	MakeMessage(
		actor: Actor,
		doWhat: string,
		target: Item,
		phraseEnd?: string,
	): Message;
	MakeMessage(
		actor: Actor,
		doWhat: string,
		third?: Color | Actor | MapObject | Item,
		phraseEnd?: string,
	): Message {
		const turn = this.m_Session.worldTime.turnCounter;

		if (third === undefined || third instanceof Color) {
			const msg = new Message(
				`${this.ActorVisibleIdentity(actor)} ${doWhat}`,
				turn,
			);
			msg.color = actor.isPlayer
				? this.PLAYER_ACTION_COLOR
				: (third ?? this.OTHER_ACTION_COLOR);
			return msg;
		}

		const target = third;
		const targetText =
			target instanceof Actor
				? this.ActorVisibleIdentity(target)
				: target instanceof MapObject
					? this.ObjectVisibleIdentity(target)
					: target.theName;

		const msg = new Message(
			`${this.ActorVisibleIdentity(actor)} ${doWhat} ${targetText}${phraseEnd ?? "."}`,
			turn,
		);
		const involvesPlayer =
			actor.isPlayer || (target instanceof Actor && target.isPlayer);
		msg.color = involvesPlayer
			? this.PLAYER_ACTION_COLOR
			: this.OTHER_ACTION_COLOR;
		return msg;
	}

