	// C# HandlePlayerOrderFollowerToPatrol — RogueGame.cs:9988
	async HandlePlayerOrderFollowerToPatrol(
		player: Actor,
		follower: Actor,
		followerFOV: FOV,
	): Promise<boolean> {
		let loop = true;
		let actionDone = false;
		const map = player.location.map!;
		let highlightedTile: Point | null = null;
		let highlightColor = Color.White;

		do {
			this.ClearOverlays();
			this.AddOverlay(
				new OverlayPopup(
					this.ORDER_MODE_TEXT,
					this.MODE_TEXTCOLOR,
					this.MODE_BORDERCOLOR,
					this.MODE_FILLCOLOR,
					new Point(0, 0),
				),
			);
			if (highlightedTile != null) {
				this.AddOverlay(
					new OverlayRect(
						highlightColor,
						new Rect(
							this.MapToScreen(highlightedTile.x, highlightedTile.y).x,
							this.MapToScreen(highlightedTile.x, highlightedTile.y).y,
							TILE_SIZE,
							TILE_SIZE,
						),
					),
				);
				const zonesHere = map.getZonesAt(highlightedTile.x, highlightedTile.y);
				if (zonesHere != null && zonesHere.length > 0) {
					const zonesNames: string[] = new Array(zonesHere.length + 1);
					zonesNames[0] = "Zone(s) here :";
					for (let i = 0; i < zonesHere.length; i++) {
						zonesNames[i + 1] = `- ${zonesHere[i].name}`;
					}
					this.AddOverlay(
						new OverlayPopup(
							zonesNames,
							Color.White,
							Color.White,
							this.POPUP_FILLCOLOR,
							this.MapToScreen(highlightedTile.x + 1, highlightedTile.y + 1),
						),
					);
				}
			}
			this.ClearMessages();
			this.AddMessage(
				new Message(
					`Ordering ${follower.name} to patrol...`,
					this.m_Session.worldTime.turnCounter,
					Color.Yellow,
				),
			);
			this.AddMessage(
				new Message(
					"<LMB> on a map position.",
					this.m_Session.worldTime.turnCounter,
					Color.LightGreen,
				),
			);
			this.RedrawPlayScreen();

			const ev = await this.WaitKeyOrMouse();
			const key = ev.key;
			const mousePos = ev.mousePos;
			const mouseButtons = ev.mouseButtons;

			if (key != null) {
				if (key.key === "Escape") loop = false;
			} else {
				const mapPos = this.MouseToMap(mousePos);
				if (map.isInBoundsPoint(mapPos) && this.IsInViewRect(mapPos)) {
					if (
						this.IsVisibleToPlayer(map, mapPos) &&
						LOS.fovHas(followerFOV, mapPos)
					) {
						let validPatrol = true;
						let reason = "";

						if (map.getZonesAt(mapPos.x, mapPos.y) == null) {
							validPatrol = false;
							reason = "no zone here";
						} else {
							const res = this.m_Rules.isWalkableFor(
								follower,
								map,
								mapPos.x,
								mapPos.y,
							);
							if (!(mapPos.equals(follower.location.position) || res.ok)) {
								validPatrol = false;
								reason = res.reason;
							}
						}

						if (validPatrol) {
							highlightedTile = mapPos;
							highlightColor = Color.LightGreen;
							if (mouseButtons === MouseButton.Left) {
								await this.DoGiveOrderTo(
									player,
									follower,
									new ActorOrder(ActorTasks.PATROL, new Location(map, mapPos)),
								);
								loop = false;
								actionDone = true;
							}
						} else {
							highlightedTile = mapPos;
							highlightColor = Color.Red;
							if (mouseButtons === MouseButton.Left) {
								this.AddMessage(
									this.MakeErrorMessage(`Can't patrol here : ${reason}`),
								);
								await this.AddMessagePressEnter();
							}
						}
					}
				}
			}
		} while (loop);

		return actionDone;
	}

	// C# HandlePlayerOrderFollowerToDropAllItems — RogueGame.cs:10103
	// async: C# blocks on DoSay's AddMessagePressEnter.
	async HandlePlayerOrderFollowerToDropAllItems(
		player: Actor,
		follower: Actor,
	): Promise<boolean> {
		if (follower.inventory!.isEmpty) return false;

		await this.DoGiveOrderTo(
			player,
			follower,
			new ActorOrder(ActorTasks.DROP_ALL_ITEMS, follower.location),
		);
		await this.DoSay(follower, player, "Well ok...", SayFlags.IS_FREE_ACTION);
		this.ModifyActorTrustInLeader(
			follower,
			follower.inventory!.countItems * Rules.TRUST_GIVE_ITEM_ORDER_PENALTY,
			true,
		);
		return true;
	}

